<?php
namespace App\Controllers;
use App\Database;
final class LeadController extends Controller {
 public function store():void{verify_csrf();$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));if($name===''||$phone===''){remember_old($_POST);flash('error','يرجى إدخال الاسم ورقم التواصل.');redirect('/#contact');}$leadId='SD-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));$data=['lead_id'=>$leadId,'name'=>mb_substr($name,0,120),'phone'=>mb_substr($phone,0,40),'email'=>mb_substr(trim((string)($_POST['email']??'')),0,190),'service'=>mb_substr(trim((string)($_POST['service']??'')),0,120),'message'=>mb_substr(trim((string)($_POST['message']??'')),0,3000),'utm_source'=>mb_substr(trim((string)($_POST['utm_source']??'')),0,120),'utm_medium'=>mb_substr(trim((string)($_POST['utm_medium']??'')),0,120),'utm_campaign'=>mb_substr(trim((string)($_POST['utm_campaign']??'')),0,120),'utm_content'=>mb_substr(trim((string)($_POST['utm_content']??'')),0,120),'landing_page'=>mb_substr(trim((string)($_POST['landing_page']??'')),0,500)];$pdo=Database::connection();if($pdo){$st=$pdo->prepare("INSERT INTO leads (lead_id,name,phone,email,service,message,status,utm_source,utm_medium,utm_campaign,utm_content,landing_page,created_at) VALUES (?,?,?,?,?,?,'new',?,?,?,?,?,NOW())");$st->execute(array_values($data));}else{$data['created_at']=date('c');file_put_contents(storage_path('logs/leads-'.date('Y-m').'.log'),json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL,FILE_APPEND|LOCK_EX);}clear_old();flash('success','تم استلام طلبك بنجاح. رقم الطلب: '.$leadId);redirect('/#contact');}
}